import sys, json
spec = json.load(sys.stdin)
paths = spec.get('paths', {})
for path, methods in paths.items():
    if 'artifact' in path.lower():
        for method, details in methods.items():
            print(f'{method.upper()} {path}')
            if 'requestBody' in details:
                content = details['requestBody'].get('content', {})
                for ct, schema in content.items():
                    ref = schema.get('schema', {}).get('\$ref', '')
                    if ref:
                        schema_name = ref.split('/')[-1]
                        schemas = spec.get('components', {}).get('schemas', {})
                        if schema_name in schemas:
                            print(f'  Schema: {schema_name}')
                            print(f'  Props: {json.dumps(schemas[schema_name].get(\"properties\", {}), indent=2)[:1000]}')
                            print(f'  Required: {schemas[schema_name].get(\"required\", [])}')
"

